0-bab5-ba5952f76c72"},{"plugin":"multimedia","state":{"explanation":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Die Innenwinkelsumme eines Trapezes beträgt immer "},{"type":"math","src":"360°","inline":true,"children":[{"text":"360°"}]},{"text":". Da du bereits drei Winkel des Trapezes kennst, kannst du damit den fehlenden Winkel ausrechnen: "}]},{"type":"p","children":[{"text":""},{"type":"math","src":"\begin{array}{rcll}
