type":"p","children":[{"text":""}]},{"type":"p","children":[{"text":"Und damit kommst du auf die gesuchte Seitenlänge "},{"type":"math","src":"\color{cc0000}\overline{BE}","inline":true,"children":[{"text":"\overline{EB}"}]},{"text":":"}]},{"type":"p","children":[{"text":""}]},{"type":"p","children":[{"text":""},{"type":"math","src":"\begin{array}{rcl}
