:[{"text":""}]},{"text":" dieses Winkels, denn das ist die Höhe des Dreiecks. Also musst du hier den Tangens benutzen:"}]}],"id":"4a9c92f0-231c-4db5-89b4-fd8cf7fef08f"},{"plugin":"multimedia","state":{"explanation":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":""},{"type":"math","src":"\begin{array}{rcl}
