:"ABCD","inline":true,"children":[{"text":"ABCD"}]},{"text":". Berechnen Sie den Radius "},{"type":"math","src":" r","inline":true,"children":[{"text":"r"}]},{"text":" des Kreissektors."}]}],"id":"b52bdcdd-d3b2-4aa1-bf72-37e75393f34f"}],"id":"219ce50d-4cd9-495e-97b3-d8221b371e3d"},"solution":{"plugin":"solution","state":{"prerequisite":{"id":"36264","title":"Kreissektor"},"strategy":{"plugin":"text","state":[{"type":"p","children":[{"text":""}]}],"id":"8ead29aa-abba-4f8f-b365-f2d956df33e8"},"steps":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"In dieser Aufgabe geht es um einen Kreissektor. Die Formel für den Flächeninhalt ist:"}]},{"type":"math","src":"A_{Sektor} = \frac{\alpha}{360}\cdot r^2\cdot \pi","inline":false,"children":[{"text":""}]},{"type":"p","children":[{"text":"Dabei ist "},{"type":"math","src":"A_{Sektor}","inline":true,"children":[{"text":"A_{Sektor}"}]},{"text":" der Flächeninhalt des Kreissektors, "},{"type":"math","src":"\alpha","inline":true,"children":[{"text":"\alpha"}]},{"text":" der "},{"type":"a","href":"/36264","children":[{"text":"Mittelpunktswinkel"}]},{"text":" und "},{"type":"math","src":" r","inline":true,"children":[{"text":"r"}]},{"text":" der Radius. Gesucht ist "},{"type":"math","src":" r","inline":true,"children":[{"text":"r"}]},{"text":". Um "},{"type":"math","src":"r","inline":true,"children":[{"text":"r"}]},{"text":" zu ermitteln, berechnest du "},{"type":"math","src":"A_{Sektor}","inline":true,"children":[{"text":"A_{Sektor}"}]},{"text":" und "},{"type":"math","src":"\alpha","inline":true,"children":[{"text":"\alpha"}]},{"text":" und stellst dann die Formel nach "},{"type":"math","src":"r","inline":true,"children":[{"text":"r"}]},{"text":" um."}]}],"id":"b3339200-3bc6-4860-9511-f4f4378ef9f6"},{"plugin":"image","state":{"src":"https://assets.serlo.org/5e70e6fa9178c_47d716aae70789057642361a112a67cdf6cfff9b.png","maxWidth":400,"caption":{"plugin":"text","state":[{"type":"p","children":[{"text":""}]}],"id":"4d6d9ca0-cd72-4f59-aba2-3cf6edc236a8"}},"id":"fac520c6-7e56-4f86-b3d2-d53c0c846b07"},{"plugin":"text","state":[{"type":"h","level":3,"children":[{"text":"Berechnung von "},{"type":"math","src":"A_{Sektor}","inline":true,"children":[{"text":"A_{Sektor}"}]},{"text":""}]},{"type":"p","children":[{"text":"Der Flächeninhalt des Kreissektors beträgt laut Aufgabenstellung "},{"type":"math","src":"5\;\%","inline":true,"children":[{"text":"5%"}]},{"text":" von dem Flächeninhalt des Trapezes. Diesen kennst du aus der vorherigen Aufgabe: "},{"type":"math","src":"A_{Trapez} = 52,1\text{cm}^2","inline":true,"children":[{"text":"A_{Trapez} = 52,1cm"}]},{"text":". Also kannst du nun mit der "},{"type":"a","href":"/2193","children":[{"text":"Formel für die Prozentrechnung"}]},{"text":" "},{"type":"math","src":"A_{Sektor}","inline":true,"children":[{"text":"A_{Sektor}"}]},{"text":" berechnen:"}]},{"type":"math","src":"A_{Sektor}=0,05\cdot52,1\ \text{cm}^2=2,6\ \text{cm}^2","inline":false,"children":[{"text":""}]}],"id":"83e01819-7875-4aa8-a932-571f5fc50ba2"},{"plugin":"text","state":[{"type":"h","level":3,"children":[{"text":"Berechnung von "},{"type":"math","src":"\alpha","inline":true,"children":[{"text":"\alpha"}]},{"text":""}]},{"type":"p","children":[{"text":"Der Mittelpunktswinkel des Kreissektors ist laut Aufgabenstellung der Winkel "},{"type":"math","src":"\sphericalangle CBA.","inline":true,"children":[{"text":"\angle CBA"}]},{"text":" Dieser entspricht dem Winkel "},{"type":"math","src":"\sphericalangle CBE = 65°","inline":true,"children":[{"text":"\angle CBE = 65°"}]},{"text":", den du schon in Aufgabe a) berechnet hast."}]}],"id":"c46d381f-f978-4cf1-b2e6-7caee02a4969"},{"plugin":"text","state":[{"type":"h","level":3,"children":[{"text":"Berechnung von r durch Umstellen der Formel"}]},{"type":"p","children":[{"text":"Setzt du nun alles in die Formel für den Flächeninhalt des Kreissektors ein, erhältst du:"}]},{"type":"math","src":"\begin{array}{rcl}
